[{"order":1,"type":"heading","text":"Writing Custom Native Bridge Modules in NativeScript"},{"order":2,"type":"paragraph","text":"NativeScript allows developers to access 100% of the native APIs on both Android (Java/Kotlin) and iOS (Objective-C/Swift) directly from JavaScript or TypeScript. When pre-built plugins do not meet your specific requirements, writing a custom native bridge module is the ideal solution."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"bullet_point","text":"A working NativeScript development environment configured for both Android and iOS."},{"order":5,"type":"bullet_point","text":"Basic understanding of TypeScript or JavaScript."},{"order":6,"type":"bullet_point","text":"Basic knowledge of native platform development (Android Java/Kotlin or iOS Swift/Objective-C)."},{"order":7,"type":"subheading","text":"Step 1: Implementing the Android Native Code"},{"order":8,"type":"paragraph","text":"For Android, you typically place your custom Java or Kotlin files inside the App_Resources/Android/src/main/java directory. Here is a simple Kotlin class that exposes a native toast message method."},{"order":9,"type":"code","text":"package com.example.custommodule

import android.content.Context
import android.widget.Toast

class NativeToastHelper {
    companion object {
        fun showCustomToast(context: Context, message: String) {
            Toast.makeText(context, message, Toast.LENGTH_SHORT).show()
        }
    }
}"},{"order":10,"type":"subheading","text":"Step 2: Implementing the iOS Native Code"},{"order":11,"type":"paragraph","text":"For iOS, add your Swift or Objective-C files inside the App_Resources/iOS directory. Make sure your classes and methods are exposed properly using @objc annotations if you are using Swift."},{"order":12,"type":"code","text":"import Foundation
import UIKit

@objcMembers
@objc(NativeAlertHelper)
public class NativeAlertHelper: NSObject {
    public static func show()
        let alert = UIAlertController(title: "Native Bridge", message: "Hello from iOS Native!", preferredStyle: .alert)
        alert.addAction(UIAlertAction(title: "OK", style: .default, handler: nil))

        DispatchQueue.main.async {
            let rootVC = UIApplication.shared.keyWindow?.rootViewController
            rootVC?.present(alert, animated: true, completion: nil)
        }
    }
}"},{"order":13,"type":"subheading","text":"Step 3: Creating the Unified Bridge in TypeScript"},{"order":14,"type":"paragraph","text":"Now, create a TypeScript file (e.g., native-bridge.ts) in your app source folder. Use NativeScript's global 'android' and 'ios' helper objects to conditionally execute platform-specific code."},{"order":15,"type":"code","text":"import { Application, Utils } from '@nativescript/core';

export class NativeBridge {
    static showMessage(msg: string) {
        if (global.isAndroid) {
            // Accessing Android classes via NativeScript's metadata generation
            com.example.custommodule.NativeToastHelper.showCustomToast(Utils.android.getApplicationContext(), msg);
        } else if (global.isIOS) {
            // Accessing iOS classes dynamically
            try {
                (global as any).NativeAlertHelper.show();
            } catch (error) {
                console.error("Error calling iOS native method: ", error);
            }
        }
    }
}"},{"order":16,"type":"subheading","text":"Step 4: Consuming the Custom Module"},{"order":17,"type":"paragraph","text":"Finally, you can import and use your custom bridge module anywhere inside your NativeScript application components, such as your main-view-model.ts."},{"order":18,"type":"code","text":"import { NativeBridge } from './native-bridge';

export class HelloWorldModel {
    onTap() {
        NativeBridge.showMessage("Hello from NativeScript Bridge!");
    }
}"},{"order":19,"type":"subheading","text":"Conclusion"},{"order":20,"type":"paragraph","text":"By writing custom native bridge modules, you unlock the full power of underlying mobile operating systems without sacrificing the efficiency of cross-platform development. Always ensure proper type checking and exception handling when communicating across the native boundary."}]
